-- Solitaire
function click_func_1player(obj, color, alt_click)
    if (Player[color].host) then
        soloSOP()
        defenseTokensSolo()
        prepGameDecksSolo()
        delete6P()
        delete2_4P()
        askForFaction()
        deleteHandZones()
    else
        broadcastToColor("Only the host may set up the game.", color, Color.Red)
    end
end

function click_func_2or4player(obj, color, alt_click)
    if (Player[color].host) then
        defensetokensMP()
        prepGameDecks2P4P()
        deleteSolo()
        delete6P()
        meeples2P4P()
        tile2P4P = getObjectFromGUID("2413f4")
