function addRandomCards()
    -- Add 10 Random Cards to Turn 1 Deck
    for i = 1, 10, 1 do
        obj = MP24Turn_1_Extras.takeObject()
        MP24Turn_1_Deck.putObject(obj)
    end
    -- Add 10 Random Cards to Turn 2 Deck
    for i = 1, 10, 1 do
        obj = MP24Turn_2_Extras.takeObject()
        MP24Turn_2_Deck.putObject(obj)
    end
    -- Add 10 Random Cards to Turn 3 Deck
    for i = 1, 10, 1 do
